(()=>{'use strict';const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));let tab='overview',data={},selected=null,busy=false;const checkoutKeys={};const $=id=>document.getElementById(id);const names={Submitted:'Waiting for assignment','In Review':'A reviewer is checking the work','Request Changes':'Changes are needed','Pending Verification':'Waiting for a second person to check','Verified':'Review and second check passed',Draft:'Still being prepared'};
async function api(path,method='GET',body){const r=await fetch('/api/'+path,{method,headers:method==='GET'?{}:{'content-type':'application/json'},...(body?{body:JSON.stringify(body)}:{})});const b=await r.json();if(!r.ok)throw Error(b.error||'Service unavailable');return b}
function button(label,action,attrs=''){return `<button class="btn" data-service="${action}" ${attrs}>${label}</button>`}function field(id,label,type='text',value=''){return `<div class="field"><label for="svc-${id}">${esc(label)}</label><input id="svc-${id}" type="${type}" value="${esc(value)}" ${type==='number'?'min="0" max="4" step="1"':''}></div>`}function area(id,label,value=''){return `<div class="field"><label for="svc-${id}">${esc(label)}</label><textarea id="svc-${id}">${esc(value)}</textarea></div>`}function choose(id,label,options){return `<div class="field"><label for="svc-${id}">${label}</label><select id="svc-${id}">${options.map(x=>`<option>${esc(x)}</option>`).join('')}</select></div>`}function val(id){return $('svc-'+id)?.value||''}function saveFile(name,b){const url=URL.createObjectURL(new Blob([JSON.stringify(b,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function shell(){return `<div class="eyebrow">Submit / review / verify / keep your records</div><h1>Academy services.</h1><p>Finish a real task, send its evidence, receive a review, make changes and earn a record of the skill you demonstrated.</p><div id="svc-message" class="notice" role="status">Connecting to your private academy account…</div><div class="pillbar" id="svc-tabs"></div><div id="svc-body"></div>`}
function draw(){if(!$('svc-body'))return;const admin=data.status?.admin;const tabs=[['overview','Start here'],['cloud','Save & recover'],['submissions','My submissions'],['review','Review desk'],['credentials','Skill records'],['orders','Orders & payments'],['requests','Help & appeals'],['monitor','Service health'],['guide','Simple words']];if(admin)tabs.push(['staff','Qualified staff'],['audit','Activity history']);$('svc-tabs').innerHTML=tabs.map(([k,v])=>button(v,'tab',`data-tab="${k}" ${k===tab?'aria-current="page"':''}`)).join('');const status=data.status||{};let out='';
if(tab==='overview')out=`<div class="stats"><div class="stat"><span>Cloud storage</span><strong>${esc(status.cloudStorage||'Unavailable')}</strong></div><div class="stat"><span>Submissions</span><strong>${(data.submissions||[]).length}</strong></div><div class="stat"><span>Qualified staff</span><strong>${status.qualifiedStaff?.count||0}</strong></div><div class="stat"><span>Your account</span><strong>${esc(status.role||'Learner')}</strong></div></div><div class="cols"><div class="card"><h2>How the review works</h2>${[['Finish the mission','Complete the twelve stages and keep your tests and corrections.'],['Send your work','Select a preserved attempt below. Its cloud copy receives a content fingerprint.'],['Get a qualified review','The owner assigns a person whose approved subject scope covers this programme.'],['Make any changes','Read the feedback, revise in the workspace and submit a new revision.'],['Get a second check','A different qualified person checks the evidence and review decision.'],['Keep a skill record','A verified mission can receive a private, checkable skill record.']].map(([a,b],i)=>`<div class="step"><b>${i+1}</b><div><strong>${a}</strong><p>${b}</p></div></div>`).join('')}</div><div class="card"><h2>Your next step</h2><p>${data.submissions?.length?'Open your submissions to read decisions and feedback.':'Prepare a mission pack in the workspace, then open My submissions to send it.'}</p>${button('Open my submissions','tab','data-tab="submissions"')}<div class="notice">A practice result, a reviewer decision, a second check and workplace experience are four different things. A mission skill record does not say you are an expert in the whole profession.</div><h3>Before collecting fees</h3><p>Connect the merchant account, approve the course and price, publish the terms and refund policy, and test payment confirmation. The order page shows the current connection status.</p></div></div>`;
if(tab==='cloud')out=`<div class="card"><h2>Keep a cloud copy</h2><p>Save your current workspace to your signed-in account. Cloud saves use a revision number so two devices cannot quietly overwrite one another.</p><p>Cloud copy: revision ${data.snapshot?.revision||0} ${data.snapshot?.updated?' / '+esc(data.snapshot.updated):'/ no copy saved yet'}</p><div class="row">${button('Save current workspace to cloud','save-cloud')}${button('Load cloud copy into workspace','load-cloud')}${button('Download cloud backup','download-cloud')}</div><div class="notice">Loading replaces local work. Export your local backup first. Restored work returns to draft and needs fresh checks; review decisions stay in the separate cloud register.</div></div>`;
if(tab==='submissions'){const attempts=window.AcademyCloud?.attempts()||[];out=`<div class="card"><h2>Ready to send</h2><p>These are the preserved attempts created when you finished a mission. Choose the revision you want a reviewer to see.</p>${attempts.length?attempts.slice().reverse().map(a=>`<div class="result row between"><div><b>${esc(a.missionId)} / revision ${a.revision}</b><p class="caption">${esc(a.time)}</p></div>${button('Send this evidence','submit',`data-id="${esc(a.id)}"`)}</div>`).join(''):'<p>No completed mission pack yet. Finish all twelve stages in the workspace.</p>'}</div><h2>Your cloud submissions</h2>${submissionList(data.submissions||[])}`}
if(tab==='review')out=`<div class="notice">${admin?'The owner may assign qualified staff. The learner, reviewer and verifier must be different people.':status.role==='Learner'?'This desk becomes available when the owner approves your subject scope as a reviewer or verifier.':'Review only work assigned to you. Explain the evidence behind each decision.'}</div>${submissionList(data.submissions||[])}${selected?reviewDetail():''}`;
if(tab==='credentials')out=`<div class="card"><h2>Issue a verified mission record</h2><p>Only independently verified submissions are eligible. Your record names the mission, evidence fingerprint, reviewer, verifier and date. It does not claim a degree or workplace experience.</p>${(data.submissions||[]).filter(s=>s.status==='Verified').map(s=>button('Issue record for '+s.mission_id,'issue',`data-id="${s.id}"`)).join('')||'<p>No verified submission yet.</p>'}</div><h2>Your private register</h2>${(data.credentials||[]).map(c=>{const b=JSON.parse(c.body);return `<div class="card"><b>${esc(b.mission)} / ${esc(c.status)}</b><p>${esc(b.scope)}</p><p class="caption">${esc(c.id)}<br>Issued ${esc(c.created)}${c.reason?'<br>Withdrawal reason: '+esc(c.reason):''}</p>${button('Download and check record','credential',`data-id="${c.id}"`)}${admin&&c.status==='Active'?button('Withdraw record','revoke',`data-id="${c.id}"`):''}</div>`}).join('')||'<div class="empty card">No skill records have been issued.</div>'}`;
if(tab==='orders')out=`<div class="card"><h2>Course access & payment</h2><p>All Academy course purchases use the same checkout. Choose an approved course offer, read its inclusions and terms, then pay through the connected merchant.</p><a class="btn primary" href="index.html#shop">Open course access & orders</a><p class="caption">Confirmed payment unlocks its stated courses and related professional programmes. Your original practice evidence and cloud snapshots remain available in this workspace.</p></div><h2>Your orders</h2>${(data.orders||[]).map(o=>`<div class="card"><b>${esc(o.title||o.product_id)} / ${esc(o.status)}</b><p>${window.AcademyShell?esc(new Intl.NumberFormat('en-IN',{style:'currency',currency:o.currency.toUpperCase()}).format(o.amount/10**(['ISK','UGX'].includes(o.currency.toUpperCase())?2:new Intl.NumberFormat('en',{style:'currency',currency:o.currency.toUpperCase()}).resolvedOptions().maximumFractionDigits))):o.amount/100}</p><a href="index.html#receipt/${encodeURIComponent(o.id)}">Open payment record and receipt</a></div>`).join('')||'<div class="empty card">No orders or charges recorded.</div>'}<p class="muted">Use Help & appeals to contact the Academy about an order. A refund request is recorded separately from the provider’s confirmed refund.</p>`;
if(tab==='requests')out=`<div class="card"><h2>Ask for help or challenge a decision</h2>${choose('kind','Request type',['Support','Appeal','Refund request','Accommodation','Mentor request','Incident'])}${field('related','Related submission, order or mission ID (optional)')}${area('message','What happened, what evidence do you have, and what outcome do you need?')}${button('Create cloud request','request')}<p class="caption">Saved requests appear here. Email notifications and a staffed response time are not yet configured.</p></div>${(data.requests||[]).map(q=>{const b=JSON.parse(q.body);return `<div class="card"><b>${esc(q.kind)} / ${esc(q.status)}</b><p>${esc(b.message)}</p><p class="caption">${esc(q.id)} / ${esc(q.created)}</p>${q.reply?'<div class="notice">Response: '+esc(q.reply)+'</div>':''}${admin?button('Respond','respond',`data-id="${q.id}"`):''}</div>`}).join('')}${data.replyId?`<div class="card">${choose('reply-status','New status',['Open','In progress','Resolved'])}${area('reply','Response and next step')}${button('Save response','save-reply')}</div>`:''}`;
if(tab==='staff')out=`<div class="notice">Approve only qualifications you have actually checked. This screen records your approval; it cannot establish that a person is professionally qualified by itself.</div><div class="card"><h2>Approve a staff member’s scope</h2>${field('staff-id','Their signed-in academy user ID')}${field('staff-name','Full name')}${choose('staff-role','Responsibility',['Reviewer','Verifier'])}${field('staff-domains','Approved programmes, separated by commas (for example DB-02, PC-01)')}${area('qualification','Qualification evidence, experience, conflict checks and why this scope is suitable')}${field('expires','Qualification review valid until','date')}${button('Save checked qualification approval','staff')}</div>${(data.staff||[]).map(p=>`<div class="card"><b>${esc(p.name)} / ${esc(p.role)}</b><p>${esc(JSON.parse(p.domains).join(', '))} / review due ${esc(p.expires)}</p><p>${esc(p.qualification)}</p><p class="caption">User ID ${esc(p.user_id)}</p></div>`).join('')}`;
if(tab==='audit')out=`<div class="notice">Server-recorded activity. This is an application log; external tamper-proof retention and monitoring are still needed.</div>${(data.audit||[]).map(a=>`<div class="timeline-item"><strong>${esc(a.action.replaceAll('_',' '))}</strong><p class="caption">${esc(a.created)} / ${esc(a.record)} / actor ${esc(a.actor)}</p></div>`).join('')||'<p>No server activity yet.</p>'}`;
if(tab==='monitor')out=`<div class="card"><h2>Current service check</h2>${Object.entries(status.services||{}).map(([k,v])=>`<div class="result"><b>${esc(k)}</b><p>${esc(v)}</p></div>`).join('')}<p>Payments: ${esc(status.payments||'Unavailable')}</p><p>Qualified staff: ${status.qualifiedStaff?.count||0}. Reviewer availability is not guaranteed.</p>${button('Check services again','refresh')}<h3>Before a public academy launch</h3><ul class="list"><li>Qualified staff actually appointed and granted separate account access.</li><li>Country-specific career content approved.</li><li>Accessibility and real browser checks completed.</li><li>Merchant, prices, policies and test payments configured.</li><li>Secure file scanning, backup recovery and independent monitoring tested.</li><li>Retention, deletion, support ownership and response times agreed.</li></ul></div><div class="notice">Your account ID: ${esc(status.userId||'Unavailable')}. Give this ID to the owner if you are being appointed as staff. The current site keeps its owner-only audience.</div>`;
if(tab==='guide')out=`<div class="grid">${[['Evidence','The work you made, the facts you used, test results and your correction history.'],['Rubric','A clear checklist for judging the quality of your work.'],['Reviewer','A person approved to judge work in a named subject.'],['Verifier','A different person who checks the evidence and the reviewer’s decision.'],['Fingerprint','A SHA-256 code calculated from the evidence. If the content changes, its code changes.'],['Revision','A numbered version of your work. A new version does not erase an older submission.'],['Appeal','A request for a decision to be reconsidered, with reasons and evidence.'],['Credential','A record of the exact skill you demonstrated and how it was assessed.'],['Entitlement','Permission to use a purchased course or service. A browser flag is not proof of access.'],['Webhook','A signed message sent by the payment provider to confirm what happened.'],['Idempotency','Sending the same request twice produces one result instead of two charges or records.'],['Conflict of interest','A relationship or personal benefit that could make a judgment unfair.'],['Recovery','Restoring saved work after a mistake or loss.'],['Accommodation','An agreed adjustment that helps a learner demonstrate the same skill fairly.'],['Production','The service people use for real work, with security, support and recovery in place.']].map(([a,b])=>`<div class="card"><h3>${a}</h3><p>${b}</p></div>`).join('')}</div>`;
$('svc-body').innerHTML=out;}
function submissionList(items){return items.map(s=>`<div class="card"><div class="row between"><div><b>${esc(s.mission_id)} / revision ${s.revision}</b><p>${esc(names[s.status]||s.status)}</p><p class="caption">${esc(s.created)} / ${esc(s.id)}</p></div>${button('Read work and feedback','detail',`data-id="${s.id}"`)}</div>${s.feedback?'<p>'+esc(s.feedback)+'</p>':''}</div>`).join('')||'<div class="empty card">No submissions are available to your account.</div>'}
function reviewDetail(){const s=selected,admin=data.status?.admin;return `<div class="card"><h2>${esc(s.mission_id)} evidence</h2><p>Content fingerprint: <code>${esc(s.hash)}</code></p><details><summary>Read preserved evidence</summary><pre>${esc(JSON.stringify(s.body,null,2))}</pre></details>${button('Download preserved evidence','download-selected')}${admin&&s.status==='Submitted'?`<h3>Assign separate qualified people</h3>${field('reviewer','Reviewer user ID')}${field('verifier','Verifier user ID')}${button('Assign review','assign')}`:''}${s.reviewer===data.status?.userId&&s.status==='In Review'?`<h3>Score the work</h3><p>0 missing, 1 weak, 2 partly meets, 3 meets, 4 exceeds. Pass requires 80/100 and every criterion at least 2.</p>${['Correctness','Handover','Verification','Reasoning','Process'].map((n,i)=>field('score'+i,n+' / 0–4','number')).join('')}${area('feedback','Evidence-based feedback, critical defects and required changes')}${choose('approve','Decision',['Request changes','Approve for independent verification'])}${button('Record review decision','review')}`:''}${s.verifier===data.status?.userId&&s.status==='Pending Verification'?`<h3>Independent check</h3>${area('feedback','Explain identity, provenance, tests, conflicts and how you checked the review')}${choose('approve','Decision',['Request changes','Verify the evidence and decision'])}${button('Record independent check','verify')}`:''}</div>`}
async function refresh(){const status=await api('status');data.status=status;const routes=['snapshot','submissions','credentials','orders','requests',...(status.admin?['staff','audit']:[])];const results=await Promise.allSettled(routes.map(x=>api(x)));const failures=[];results.forEach((r,i)=>{if(r.status==='fulfilled')data[routes[i]]=r.value.items||r.value;else failures.push(routes[i]+': '+r.reason.message)});if(!$('svc-message'))return;$('svc-message').textContent=failures.length?'Some records could not load. '+failures.join(' / '):'Connected. Your records are private to your signed-in account and assigned staff.';draw()}
async function start(){try{await refresh()}catch(e){if($('svc-message'))$('svc-message').textContent=e.message;draw()}}
document.addEventListener('click',async event=>{const el=event.target.closest('[data-service]');if(!el||busy)return;const a=el.dataset.service;if(a==='tab'){tab=el.dataset.tab;draw();return}busy=true;el.disabled=true;try{if(a==='refresh')await refresh();if(a==='save-cloud'){const b=await api('snapshot','PUT',{body:window.AcademyCloud.snapshot(),expectedRevision:data.snapshot?.revision||0});data.snapshot={...b,updated:new Date().toISOString()};await refresh()}if(a==='load-cloud'){const b=await api('snapshot');if(!b.body)throw Error('No cloud copy has been saved yet.');if(confirm('Replace your local workspace with the cloud draft? Export your local backup first.')){window.AcademyCloud.restore(b.body);$('svc-message').textContent='Cloud work restored as drafts. Rerun the checks before submission.';draw()}}if(a==='download-cloud'){const b=await api('snapshot');if(!b.body)throw Error('No cloud copy yet.');saveFile('DigitalBurj-Cloud-Backup.json',b.body)}if(a==='submit'){const attempt=window.AcademyCloud.attempts().find(x=>x.id===el.dataset.id);if(!attempt)throw Error('Attempt not found');await api('submissions','POST',{missionId:attempt.missionId,evidence:attempt.evidence});await refresh()}if(a==='detail'){selected=await api('submissions/'+el.dataset.id);tab='review';draw()}if(a==='download-selected')saveFile(selected.mission_id+'-cloud-evidence.json',selected);if(a==='staff'){await api('staff','POST',{userId:val('staff-id').trim(),name:val('staff-name'),role:val('staff-role'),domains:val('staff-domains').split(',').map(s=>s.trim()),qualification:val('qualification'),expires:val('expires')});await refresh()}if(['assign','review','verify'].includes(a)){await api('review','POST',{id:selected.id,version:selected.version,action:a,reviewer:val('reviewer'),verifier:val('verifier'),scores:[0,1,2,3,4].map(i=>val('score'+i)===''?NaN:Number(val('score'+i))),feedback:val('feedback'),approve:val('approve').startsWith('Approve')||val('approve').startsWith('Verify')});selected=await api('submissions/'+selected.id);await refresh()}if(a==='issue'){await api('credentials','POST',{submissionId:el.dataset.id});await refresh()}if(a==='credential'){const c=await api('credentials/'+el.dataset.id);saveFile(c.id+'.json',c)}if(a==='revoke'){const reason=prompt('Explain the evidence-based reason for withdrawing this record (at least 50 characters).');if(reason){await api('revoke','POST',{id:el.dataset.id,reason});await refresh()}}if(a==='checkout'){const b=await api('checkout','POST',{productId:val('product'),requestKey:checkoutKeys[val('product')]||(checkoutKeys[val('product')]=crypto.randomUUID())});location.assign(b.url)}if(a==='request'){await api('requests','POST',{kind:val('kind'),message:val('message'),relatedId:val('related')});await refresh()}if(a==='respond'){data.replyId=el.dataset.id;draw()}if(a==='save-reply'){await api('request-reply','POST',{id:data.replyId,status:val('reply-status'),reply:val('reply')});data.replyId=null;await refresh()}}catch(e){if($('svc-message'))$('svc-message').textContent=e.message}finally{busy=false;el.disabled=false}});window.AcademyService={shell,start};})();
